export const FLOURISH_DATA_URIS: Record<string, string> = {
  '1': 'data:image/png;base64,',
  'flourish_1_blue': 'data:image/png;base64,',
  '/images/flourishes/flourish_1_blue.png': 'data:image/png;base64,',
  'images/flourishes/flourish_1_blue.png': 'data:image/png;base64,',
  '2': 'data:image/png;base64,',
  'flourish_2_blue': 'data:image/png;base64,',
  '/images/flourishes/flourish_2_blue.png': 'data:image/png;base64,',
  'images/flourishes/flourish_2_blue.png': 'data:image/png;base64,',
  '3': 'data:image/png;base64,',
  'flourish_3_blue': 'data:image/png;base64,',
  '/images/flourishes/flourish_3_blue.png': 'data:image/png;base64,',
  'images/flourishes/flourish_3_blue.png': 'data:image/png;base64,',
  '4': 'data:image/png;base64,',
  'flourish_4_blue': 'data:image/png;base64,',
  '/images/flourishes/flourish_4_blue.png': 'data:image/png;base64,',
  'images/flourishes/flourish_4_blue.png': 'data:image/png;base64,',
  '5': 'data:image/png;base64,',
  'flourish_5_blue': 'data:image/png;base64,',
  '/images/flourishes/flourish_5_blue.png': 'data:image/png;base64,',
  'images/flourishes/flourish_5_blue.png': 'data:image/png;base64,',
};

export const DEFAULT_FLOURISH_DATA_URI = FLOURISH_DATA_URIS['1'];

export function resolveFlourishUrl(urlOrId?: string): string {
  if (!urlOrId) return DEFAULT_FLOURISH_DATA_URI;
  if (urlOrId.startsWith('data:')) return urlOrId;
  return FLOURISH_DATA_URIS[urlOrId] || DEFAULT_FLOURISH_DATA_URI;
}
